// Tools templates: working surfaces, a board of cards and a file explorer.
import { useState } from '../react.js';
import { Card } from '../components/Card.jsx';
import { Stack } from '../components/Layout.jsx';
import { Badge } from '../components/Badge.jsx';
import { Button } from '../components/Button.jsx';
import { Avatar, AvatarGroup } from '../components/Avatar.jsx';
import { List, ListItem } from '../components/List.jsx';
import { Breadcrumbs } from '../components/Breadcrumbs.jsx';
import { SegmentedControl } from '../components/SegmentedControl.jsx';
import { Table, proportional } from '../components/Table.jsx';
import { Icon } from '../components/Icon.jsx';
import { Page, PageHeader, Panel } from './_kit.jsx';

const COLUMNS = [
  { id: 'todo', title: 'To do', cards: [{ t: 'Write the launch notes', tag: 'Docs', who: ['Hana Kim'] }, { t: 'Audit the pricing page', tag: 'Growth', who: ['Sofia Alvarez', 'Daniel Okafor'] }] },
  { id: 'doing', title: 'In progress', cards: [{ t: 'Migrate billing to the new provider', tag: 'Backend', who: ['Lucas Meyer'] }, { t: 'Design the empty states', tag: 'Design', who: ['Amelia Brooks'] }, { t: 'Fix the login loop', tag: 'Bug', who: ['Oliver Grant'] }] },
  { id: 'done', title: 'Done', cards: [{ t: 'Ship the new onboarding', tag: 'Product', who: ['Priya Raman', 'Noah Ito'] }] },
];

export function KanbanBoard() {
  return (
    <Page width={1200}>
      <PageHeader title="Sprint board" subtitle="Cards move left to right as work progresses" actions={<Button label="Add card" size="sm" variant="primary" />} />
      <div className="tpl-kanban">
        {COLUMNS.map((c) => (
          <Stack key={c.id} gap={3}>
            <Stack direction="row" justify="space-between" align="center"><h2 className="tpl-h2">{c.title}</h2><Badge type="counter" variant="secondary" label={c.cards.length} /></Stack>
            {c.cards.map((card) => (
              <Card variant="surface" key={card.t} padding={4}>
                <Stack gap={3}>
                  <span className="tpl-text">{card.t}</span>
                  <Stack direction="row" justify="space-between" align="center"><Badge variant="secondary" label={card.tag} /><AvatarGroup size="sm">{card.who.map((n) => <Avatar key={n} alt={n} size="sm" />)}</AvatarGroup></Stack>
                </Stack>
              </Card>
            ))}
          </Stack>
        ))}
      </div>
    </Page>
  );
}

const TREE = [{ name: 'Design', files: [{ id: 1, name: 'Brand guidelines.pdf', size: '4.2 MB', modified: 'Oct 21' }, { id: 2, name: 'Icons.fig', size: '12 MB', modified: 'Oct 18' }] }, { name: 'Engineering', files: [{ id: 3, name: 'Architecture.md', size: '18 KB', modified: 'Oct 25' }, { id: 4, name: 'Release plan.xlsx', size: '210 KB', modified: 'Oct 12' }] }, { name: 'Finance', files: [{ id: 5, name: 'Budget 2027.xlsx', size: '540 KB', modified: 'Oct 2' }] }];

export function FileExplorer() {
  const [folder, setFolder] = useState('Design');
  const [view, setView] = useState('list');
  const [file, setFile] = useState(null);
  const files = TREE.find((f) => f.name === folder).files;
  return (
    <Page width={1120}>
      <PageHeader title="Files" actions={<SegmentedControl label="View" size="sm" items={[{ value: 'list', label: 'List' }, { value: 'grid', label: 'Grid' }]} value={view} onValueChange={setView} />} />
      <Breadcrumbs items={[{ label: 'Files', href: '#' }, { label: folder }]} />
      <div className="tpl-split" style={{ gridTemplateColumns: '220px minmax(0, 1fr) 260px' }}>
        <Card variant="surface" padding={2}><List>{TREE.map((f) => <ListItem key={f.name} icon={<Icon name="Folder" size={20} />} active={f.name === folder} onClick={() => { setFolder(f.name); setFile(null); }}>{f.name}</ListItem>)}</List></Card>
        {view === 'list' ? (
          <Table data={files} caption={folder} hoverable onRowClick={(r) => setFile(r)} columns={[{ key: 'name', header: 'Name', width: proportional(3, { minWidth: 160 }), renderCell: (r) => <Stack direction="row" gap={2} align="center"><Icon name="File01" size={20} />{r.name}</Stack> }, { key: 'size', header: 'Size', width: proportional(1, { minWidth: 70 }) }, { key: 'modified', header: 'Modified', width: proportional(1, { minWidth: 80 }) }]} />
        ) : (
          <div className="tpl-files-grid">{files.map((f) => <Card variant="surface" key={f.id} padding={4}><Stack gap={2} align="center"><Icon name="File01" size={32} /><span className="tpl-text">{f.name}</span></Stack></Card>)}</div>
        )}
        <Panel title={file ? file.name : 'Details'}>{file ? <Stack gap={2}><span className="tpl-meta">{`Size ${file.size}`}</span><span className="tpl-meta">{`Modified ${file.modified}`}</span><Button label="Download" variant="secondary" size="sm" /></Stack> : <span className="tpl-meta">Select a file to see its details</span>}</Panel>
      </div>
    </Page>
  );
}

// Shared pieces of the templates: the page shell, small data displays built from tokens, and the mock data.
import { Children } from '../react.js';
import { Card } from '../components/Card.jsx';
import { Stack, Grid } from '../components/Layout.jsx';
import { Badge } from '../components/Badge.jsx';
import { Breadcrumbs } from '../components/Breadcrumbs.jsx';
import { Avatar } from '../components/Avatar.jsx';
import { Icon } from '../components/Icon.jsx';

/** The page of a template: a column that is centered and at most `width` wide. The title belongs to the first block under it (rule H6): they are one group, 16px apart, and the other blocks are a section apart. */
export function Page({ width = 1120, padding = 6, gap, children, ...rest }) {
  const kids = Children.toArray(children);
  // the header (with breadcrumbs above it) and the first block under it are one group; whatever came before it (a banner) stays apart
  const at = kids.findIndex((k) => k.type === PageHeader);
  let body = kids;
  if (at >= 0 && at < kids.length - 1) {
    const crumbs = at > 0 && kids[at - 1].type === Breadcrumbs;
    const from = crumbs ? at - 1 : at;
    const title = crumbs ? <div className="tpl-page__head" key="title">{kids[at - 1]}{kids[at]}</div> : kids[at];
    const group = <div className="tpl-page__head tpl-page__head--body" key="head">{title}{kids[at + 1]}</div>;
    body = [...kids.slice(0, from), group, ...kids.slice(at + 2)];
  }
  return (
    <main className="tpl-page" style={{ maxWidth: width, padding: `calc(var(--baseui-spacing-${padding}, 24px))`, ...(gap ? { gap: `var(--baseui-spacing-${gap})` } : {}) }} {...rest}>
      {body}
    </main>
  );
}

/** A title with a line under it and actions on the right. */
export function PageHeader({ title, subtitle, actions, level = 1 }) {
  const H = `h${level}`;
  return (
    <header className="tpl-header">
      <div className="tpl-header__text">
        <H className="tpl-title">{title}</H>
        {subtitle && <p className="tpl-subtitle">{subtitle}</p>}
      </div>
      {actions && <div className="tpl-header__actions">{actions}</div>}
    </header>
  );
}

/** A grid that fills the width with columns of at least `min` px. */
export function Fluid({ min = 240, gap = 4, children, ...rest }) {
  return <Grid columns={`repeat(auto-fit, minmax(min(${min}px, 100%), 1fr))`} gap={gap} {...rest}>{children}</Grid>;
}

/** A number with its label and its change against the previous period. */
export function Tile({ label, value, delta, tone, spark, footnote }) {
  const status = tone || (delta == null ? undefined : delta >= 0 ? 'success' : 'error');
  return (
    <Card variant="surface" padding={4}>
      <Stack gap={1}>
        <span className="tpl-meta">{label}</span>
        <span className="tpl-figure">{value}</span>
        <Stack direction="row" gap={2} align="center">
          {delta != null && <Badge variant={status} label={`${delta >= 0 ? '+' : ''}${delta}%`} />}
          {footnote && <span className="tpl-meta">{footnote}</span>}
        </Stack>
        {spark && <Spark data={spark} />}
      </Stack>
    </Card>
  );
}

/** A line of points drawn in the accent color. */
export function Spark({ data, height = 40 }) {
  const max = Math.max(...data);
  const min = Math.min(...data);
  const w = 100;
  const pts = data.map((v, i) => `${(i / (data.length - 1)) * w},${height - 4 - ((v - min) / (max - min || 1)) * (height - 8)}`).join(' ');
  return (
    <svg className="tpl-spark" viewBox={`0 0 ${w} ${height}`} preserveAspectRatio="none" role="img" aria-label={`Trend, from ${data[0]} to ${data[data.length - 1]}`} style={{ height }}>
      <polyline points={pts} fill="none" stroke="var(--baseui-background-brand)" strokeWidth="2" vectorEffect="non-scaling-stroke" strokeLinejoin="round" strokeLinecap="round" />
    </svg>
  );
}

/** Vertical bars; `series` is [{ label, value }]. */
export function Bars({ series, height = 160, label = 'Bar chart' }) {
  const max = Math.max(...series.map((s) => s.value));
  return (
    <div className="tpl-bars" role="img" aria-label={label} style={{ height }}>
      {series.map((s) => (
        <div key={s.label} className="tpl-bars__col">
          <div className="tpl-bars__bar" style={{ height: `${(s.value / max) * 100}%` }} title={`${s.label}: ${s.value}`} />
          <span className="tpl-meta">{s.label}</span>
        </div>
      ))}
    </div>
  );
}

/** Horizontal bars with their values, for a ranking or a breakdown. */
export function HBars({ series }) {
  const max = Math.max(...series.map((s) => s.value));
  return (
    <Stack gap={3}>
      {series.map((s) => (
        <div key={s.label} className="tpl-hbar">
          <span className="tpl-hbar__label">{s.label}</span>
          <span className="tpl-hbar__track"><span className="tpl-hbar__fill" style={{ width: `${(s.value / max) * 100}%` }} /></span>
          <span className="tpl-hbar__value">{s.text ?? s.value}</span>
        </div>
      ))}
    </Stack>
  );
}

/** A card with a title row (and actions) over its content. */
export function Panel({ title, subtitle, actions, padding = 4, children, ...rest }) {
  return (
    <Card variant="surface" padding={padding} {...rest}>
      <Stack gap={4}>
        {(title || actions) && (
          <div className="tpl-panel__head">
            <div>
              <h2 className="tpl-h2">{title}</h2>
              {subtitle && <p className="tpl-meta">{subtitle}</p>}
            </div>
            {actions}
          </div>
        )}
        {children}
      </Stack>
    </Card>
  );
}

/** The side navigation shared by the shells and the app-like templates. */
export function SideNav({ items, active, title = 'Acme', footer }) {
  return (
    <nav className="tpl-sidenav" aria-label="Main">
      <div className="tpl-sidenav__brand">{title}</div>
      <ul>
        {items.map((i) => (
          <li key={i.label}>
            <a href="#" className="tpl-sidenav__link" aria-current={i.label === active ? 'page' : undefined} onClick={(e) => e.preventDefault()}>
              <Icon name={i.icon} size={20} />
              <span>{i.label}</span>
            </a>
          </li>
        ))}
      </ul>
      {footer}
    </nav>
  );
}

export const NAV = [
  { label: 'Overview', icon: 'Home01' },
  { label: 'Reports', icon: 'BarChart01' },
  { label: 'Customers', icon: 'Users01' },
  { label: 'Messages', icon: 'Mail01' },
  { label: 'Settings', icon: 'Settings01' },
];

export const PEOPLE = [
  { id: 1, name: 'Amelia Brooks', role: 'Design', email: 'amelia@acme.com', status: 'Active', city: 'Berlin', amount: 4820 },
  { id: 2, name: 'Noah Ito', role: 'Engineering', email: 'noah@acme.com', status: 'Active', city: 'Tokyo', amount: 3150 },
  { id: 3, name: 'Priya Raman', role: 'Product', email: 'priya@acme.com', status: 'Away', city: 'Bangalore', amount: 2740 },
  { id: 4, name: 'Lucas Meyer', role: 'Engineering', email: 'lucas@acme.com', status: 'Active', city: 'Zurich', amount: 5260 },
  { id: 5, name: 'Sofia Alvarez', role: 'Marketing', email: 'sofia@acme.com', status: 'Invited', city: 'Madrid', amount: 1980 },
  { id: 6, name: 'Daniel Okafor', role: 'Sales', email: 'daniel@acme.com', status: 'Active', city: 'Lagos', amount: 3890 },
  { id: 7, name: 'Hana Kim', role: 'Design', email: 'hana@acme.com', status: 'Away', city: 'Seoul', amount: 2210 },
  { id: 8, name: 'Oliver Grant', role: 'Support', email: 'oliver@acme.com', status: 'Active', city: 'Dublin', amount: 1670 },
];

export const STATUS_TONE = { Active: 'success', Away: 'warning', Invited: 'info', Paused: 'secondary', Blocked: 'error' };

export const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'].map((label, i) => ({ label, value: [42, 51, 47, 63, 58, 72, 69, 81, 77, 90, 86, 98][i] }));

export const money = (n) => `$${n.toLocaleString('en-US')}`;

export const Person = ({ name, size = 'md' }) => (
  <Stack direction="row" gap={2} align="center">
    <Avatar alt={name} size={size} />
    <span>{name}</span>
  </Stack>
);

/* Layout of the templates: small, built from the tokens. The components bring their own styles. */
.tpl-page { margin: 0 auto; box-sizing: border-box; width: 100%; display: flex; flex-direction: column; gap: var(--baseui-spacing-10); }
.tpl-page__head { display: flex; flex-direction: column; gap: var(--baseui-spacing-3); min-width: 0; }
.tpl-page__head--body { gap: var(--bui-rel-related); }
.tpl-header { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: var(--baseui-spacing-4); }
.tpl-header__actions { display: flex; flex-wrap: wrap; gap: var(--baseui-spacing-2); align-items: center; }
.tpl-title { margin: 0; font: var(--baseui-typography-header-28); color: var(--baseui-text-and-icon-primary); }
.tpl-h2 { margin: 0; font: var(--baseui-typography-text-16-bold); color: var(--baseui-text-and-icon-primary); }
.tpl-subtitle { margin: 0; color: var(--baseui-text-and-icon-primary); font: var(--baseui-typography-text-16-regular); line-height: 20px; }
.tpl-meta { color: var(--baseui-text-and-icon-secondary); font: var(--baseui-typography-text-14-regular); margin: 0; }
.tpl-text { color: var(--baseui-text-and-icon-primary); font: var(--baseui-typography-text-16-regular); margin: 0; }
.tpl-figure { color: var(--baseui-text-and-icon-primary); font: var(--baseui-typography-header-28); }
.tpl-panel__head { display: flex; align-items: flex-start; justify-content: space-between; gap: var(--baseui-spacing-3); flex-wrap: wrap; }
.tpl-spark { width: 100%; display: block; }
.tpl-bars { display: flex; align-items: stretch; gap: var(--baseui-spacing-2); }
.tpl-bars__col { flex: 1; display: flex; flex-direction: column; justify-content: flex-end; align-items: center; gap: var(--baseui-spacing-1); min-width: 0; }
.tpl-bars__bar { width: 100%; border-radius: var(--baseui-radius-md) var(--baseui-radius-md) 0 0; background: var(--baseui-background-brand); min-height: 2px; }
.tpl-hbar { display: grid; grid-template-columns: minmax(80px, 140px) 1fr auto; gap: var(--baseui-spacing-3); align-items: center; }
.tpl-hbar__label { color: var(--baseui-text-and-icon-primary); font: var(--baseui-typography-text-14-regular); }
.tpl-hbar__track { height: 8px; border-radius: var(--baseui-radius-full); background: var(--baseui-background-tertiary); overflow: hidden; }
.tpl-hbar__fill { display: block; height: 100%; border-radius: var(--baseui-radius-full); background: var(--baseui-background-brand); }
.tpl-hbar__value { color: var(--baseui-text-and-icon-primary); font: var(--baseui-typography-text-14-regular); font-variant-numeric: tabular-nums; }
.tpl-split { display: grid; grid-template-columns: minmax(0, 1fr) 320px; gap: var(--baseui-spacing-6); align-items: start; }
.tpl-shell { display: grid; grid-template-columns: 240px minmax(0, 1fr); min-height: 100vh; }
.tpl-shell__main { min-width: 0; }
.tpl-sidenav { border-right: 1px solid var(--baseui-border-primary); background: var(--baseui-extensions-background-surface); padding: var(--baseui-spacing-4); display: flex; flex-direction: column; gap: var(--baseui-spacing-6); }
.tpl-sidenav ul { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: var(--baseui-spacing-1); }
.tpl-sidenav__brand { font: var(--baseui-typography-text-16-bold); color: var(--baseui-text-and-icon-primary); padding: var(--baseui-spacing-2); }
.tpl-sidenav__link { display: flex; align-items: center; gap: var(--baseui-spacing-3); min-height: 40px; padding: 0 var(--baseui-spacing-3); border-radius: var(--baseui-radius-lg); color: var(--baseui-text-and-icon-primary); text-decoration: none; font: var(--baseui-typography-text-14-regular); }
.tpl-sidenav__link:hover { background: var(--baseui-background-transparent-hover); }
.tpl-sidenav__link[aria-current="page"] { background: var(--baseui-background-secondary); font-weight: 600; }
.tpl-center { min-height: 100vh; display: grid; place-items: center; padding: var(--baseui-spacing-6); box-sizing: border-box; background: var(--baseui-background-secondary); }
.tpl-hero { text-align: center; display: flex; flex-direction: column; align-items: center; gap: var(--baseui-spacing-6); padding: var(--baseui-spacing-16) var(--baseui-spacing-4); }
.tpl-hero h1 { margin: 0; max-width: 18ch; font: var(--baseui-typography-header-48); color: var(--baseui-text-and-icon-primary); }
.tpl-hero p { margin: 0; max-width: 56ch; }
.tpl-image { aspect-ratio: 4 / 3; width: 100%; border-radius: var(--baseui-radius-xl); background: linear-gradient(135deg, var(--baseui-background-tertiary), var(--baseui-background-disabled)); display: grid; place-items: center; color: var(--baseui-text-and-icon-secondary); }
.tpl-prose { max-width: 70ch; display: flex; flex-direction: column; gap: var(--baseui-spacing-10); }
.tpl-step { display: flex; flex-direction: column; gap: var(--baseui-spacing-3); }
.tpl-prose p { margin: 0; color: var(--baseui-text-and-icon-primary); font: var(--baseui-typography-text-16-regular); }
.tpl-chat { display: flex; flex-direction: column; gap: var(--baseui-spacing-4); }
.tpl-bubble { max-width: 70%; padding: var(--baseui-spacing-3) var(--baseui-spacing-4); border-radius: var(--baseui-radius-2xl); font: var(--baseui-typography-text-16-regular); color: var(--baseui-text-and-icon-primary); background: var(--baseui-background-secondary); }
.tpl-bubble--me { align-self: flex-end; background: var(--baseui-background-tertiary); }
.tpl-kanban { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(240px, 1fr); gap: var(--baseui-spacing-4); overflow-x: auto; }
.tpl-heat { display: grid; gap: 2px; }
.tpl-heat__cell { height: 32px; border-radius: var(--baseui-radius-sm); display: grid; place-items: center; font: var(--baseui-typography-text-12-regular); color: var(--baseui-text-and-icon-primary); }
@media (max-width: 860px) {
  .tpl-split { grid-template-columns: minmax(0, 1fr); }
  .tpl-shell { grid-template-columns: minmax(0, 1fr); }
  .tpl-sidenav { border-right: 0; border-bottom: 1px solid var(--baseui-border-primary); }
  .tpl-sidenav ul { flex-direction: row; overflow-x: auto; }
  .tpl-bubble { max-width: 90%; }
}
.tpl-steps { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: var(--baseui-spacing-4); font: var(--baseui-typography-text-16-regular); color: var(--baseui-text-and-icon-secondary); }
.tpl-steps li { display: flex; align-items: center; gap: var(--baseui-spacing-3); }
.tpl-steps li[aria-current="step"] { color: var(--baseui-text-and-icon-primary); font-weight: 600; }
.tpl-steps__dot { width: 28px; height: 28px; border-radius: var(--baseui-radius-full); display: grid; place-items: center; background: var(--baseui-background-tertiary); color: var(--baseui-text-and-icon-primary); font: var(--baseui-typography-text-14-semi-bold); }
.tpl-steps li[aria-current="step"] .tpl-steps__dot { background: var(--baseui-background-brand); color: var(--baseui-extensions-text-and-icon-on-brand); }
.tpl-login-split { display: grid; grid-template-columns: 1fr 1fr; min-height: 100vh; }
.tpl-login-split__form { display: grid; place-items: center; padding: var(--baseui-spacing-8); }
.tpl-login-split__aside { display: grid; place-items: center; padding: var(--baseui-spacing-12); background: var(--baseui-background-brand); }
.tpl-login-split__aside p { margin: 0; max-width: 20ch; font: var(--baseui-typography-header-32); color: var(--baseui-extensions-text-and-icon-on-brand); }
@media (max-width: 860px) { .tpl-login-split { grid-template-columns: 1fr; } .tpl-login-split__aside { display: none; } }
.tpl-files-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(140px, 1fr)); gap: var(--baseui-spacing-3); align-content: start; }
@media (max-width: 860px) { .tpl-split[style] { grid-template-columns: minmax(0, 1fr) !important; } }
.tpl-code { margin: 0; padding: var(--baseui-spacing-4); border-radius: var(--baseui-radius-xl); background: var(--baseui-background-secondary); color: var(--baseui-text-and-icon-primary); font: var(--baseui-typography-text-14-regular); font-family: var(--baseui-typography-font-family-mono, monospace); overflow-x: auto; }
.tpl-composer { position: sticky; bottom: var(--baseui-spacing-4); }
.tpl-masonry { columns: 3 220px; column-gap: var(--baseui-spacing-4); }
.tpl-masonry__item { break-inside: avoid; margin-bottom: var(--baseui-spacing-4); }
.tpl-topbar { display: flex; align-items: center; gap: var(--baseui-spacing-6); padding: var(--baseui-spacing-3) var(--baseui-spacing-6); border-bottom: 1px solid var(--baseui-border-primary); }
.tpl-topbar > :nth-child(2) { flex: 1; min-width: 0; }
.tpl-shell__bottom { display: none; }
@media (max-width: 860px) { .tpl-shell--responsive .tpl-shell__side { display: none; } .tpl-shell--responsive .tpl-shell__bottom { display: block; position: sticky; bottom: 0; } .tpl-topbar { padding-inline: var(--baseui-spacing-4); gap: var(--baseui-spacing-3); } }
